ethod"},"defaultValue":"letterforms as architecture","id":"method","label":"Visual method","type":"text"},{"binding":{"mode":"variable","target":"structure"},"defaultValue":"stairs, shadows, and occlusion make the word feel inhabitable","id":"structure","label":"Composition rule","type":"textarea"},{"binding":{"mode":"generation","target":"aspectRatio"},"defaultValue":"4:5","id":"aspect-ratio","label":"Format","options":[{"label":"Portrait 4:5","value":"4:5"},{"label":"Tall 9:16","value":"9:16"},{"label":"Square 1:1","value":"1:1"},{"label":"Landscape 3:2","value":"3:2"}],"type":"aspect-ratio"}],"description":"Turn a short word into a believable place a subject can cross or enter.","generation":{"capability":"image-generation","defaultOperation":"generate","defaultVariationCount":1,"delivery":"webmcp-import","operations":["generate","edit","variation","upscale"],"preferredMimeTypes":["image/png","image/webp"],"provider":"codex"},"id":"walkable-word","layout":{"arrangement":"prompt-left-output-right","mode":"seeded","preserveManualGeometry":true},"outputs":[{"aspectRatio":"4:5","count":1,"id":"primary","kind":"image","label":"Result","layoutHint":"hero","operations":["generate","edit","variation","upscale"],"required":true,"role":"primary"}],"preservation":[{"appliesTo":["method","structure"],"description":"Preserve the defining letterforms as architecture method and this composition obligation: stairs, shadows, and occlusion make the word feel inhabitable.","id":"creative-mechanism","label":"Creative mechanism","strength":"must"}],"prompt":{"agentInstructions":"Resolve all visible controls and reference obligations before generation. Produce one candidate by default and return it to the primary output slot.","body":"Turn a short word into a believable place a subject can cross or enter. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.","title":"Creative direction","variables":[{"defaultValue":"A lone cyclist moving through the word CROSSING","id":"brief","label":"Creative brief","required":true,"type":"text"},{"defaultValue":"letterforms as architecture","id":"method","label":"Visual method","type":"string"},{"defaultValue":"stairs, shadows, and occlusion make the word feel inhabitable","id":"structure","label":"Composition rule","type":"string"}]},"schema":"prompt-canvas.prompt-workspace-template@2","source":{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Walkable word"},"status":"starter","tags":["type as space","word as architecture","person walking through letters"],"thumbnail":{"alt":"First-party graphic preview for Walkable word, illustrating letterforms as architecture.","assetPath":"/recipe-thumbnails/original-systems/walkable-word.svg"},"title":"Walkable word","version":1,"x-agent-authoring":{"generationDefault":1,"origin":"independent-first-party","reviewState":"owner-requested-original-authoring"},"x-discovery":{"badges":["No photo needed","Makes 1 image"],"collection":"original-systems","complexity":"guided","inputModes":["text"],"inputSummary":["A creative brief"],"intentAliases":["word as architecture","person walking through letters","architectural typography"],"intents":["create"],"outputKinds":["image"],"preservationNeeds":[],"requiredInputSummary":["A short creative brief"],"subjectKinds":["person","object","place","concept"],"thumbnail":{"alt":"First-party graphic preview for Walkable word, illustrating letterforms as architecture.","src":"/recipe-thumbnails/original-systems/walkable-word.svg"},"userPromise":"Turn a short word into a believable place a subject can cross or enter."},"x-presentation":{"advancedControlIds":[],"initialView":"canvas","primaryControlIds":["brief","method","structure","aspect-ratio"],"resultEmphasis":"hero","showPromptByDefault":false}}', 'prompt-canvas.prompt-workspace-template@2', 'sha256:c33802829fb632405101bc8d54f520887a01a22305f55514e6276184dd68f9c5', 'Turn a short word into a believable place a subject can cross or enter. Create an original, polished image for this brief: {{brief}}. Use {{method}} as the visual method. Organize the image so {{structure}}. Favor one clear focal idea, intentional negative space, coherent lighting, believable depth, and material-specific detail. Do not add unrelated text, logos, watermarks, copied characters, or unsupported factual claims.', NULL, '{"creator":"Prompt Canvas","kind":"first-party","notes":"Independently authored for Prompt Canvas from a high-level creative use case.","promptUsage":"original","title":"Walkable word"}', 'Initial official catalog publication.', '2026-09-03T00:00:00Z', '2026-09-03T00:00:00Z');
